#include "serialportreader.h"
#include <QSerialPortInfo>
#include <QCoreApplication>
#include <QSettings>
#include <QDebug>

SerialPortReader::SerialPortReader(QObject *parent) :
    QObject(parent)
{
    // Load port name from configuration
    QSettings settings;
    m_portName = settings.value("serialPort/portName", "COM8").toString();
    m_serialPort.setPortName(m_portName);
    m_serialPort.setBaudRate(QSerialPort::Baud115200);

    connect(&m_serialPort, &QSerialPort::readyRead, this, &SerialPortReader::handleReadyRead);
    connect(&m_serialPort, &QSerialPort::errorOccurred, this, &SerialPortReader::handleError);
}

SerialPortReader::~SerialPortReader()
{
    if (m_serialPort.isOpen())
        m_serialPort.close();
}

void SerialPortReader::start()
{
    if (m_serialPort.open(QIODevice::ReadOnly)) {
        qDebug() << "Started reading from" << m_serialPort.portName();
    } else {
        qDebug() << "Could not open port" << m_serialPort.portName() << ":" << m_serialPort.errorString();
    }
}

void SerialPortReader::handleReadyRead()
{
    QByteArray data = m_serialPort.readAll();
    if (data.size() > MAX_DATA_SIZE) {
        qDebug() << "Data size exceeds maximum allowed size. Dropping data.";
        return;
    }
    emit newData(data);
}

void SerialPortReader::handleError(QSerialPort::SerialPortError error)
{
    if (error == QSerialPort::ReadError) {
        qDebug() << "An I/O error occurred while reading the data from port" << m_serialPort.portName() << ", error:" << m_serialPort.errorString();
    } else if (error == QSerialPort::ResourceError) {
        qDebug() << "Resource error occurred while reading the data from port" << m_serialPort.portName() << ", error:" << m_serialPort.errorString();
    } else {
        qDebug() << "An error occurred while reading the data from port" << m_serialPort.portName() << ", error:" << m_serialPort.errorString();
    }
}
